/**
 * The 54 parashiyot of the Torah, each divided into its 7 aliyot (plus Maftir),
 * from @hebcal/leyning (the open Torah-reading data used by many synagogue
 * calendars). `alt` notes where some communities divide differently.
 * `haftarah` is the Sephardic haftarah; confirm Syrian custom with your Hazzan.
 * Generated by script; edit freely to match your community's divisions.
 */

export interface Aliyah {
  /** 1–7, or "M" for Maftir. */
  n: number | "M";
  /** First and last pasuk, "chapter:verse". */
  from: string;
  to: string;
  pesukim: number;
  alt?: string;
}

export interface Parasha {
  id: string;
  en: string;
  he: string;
  /** Book id, as in TANAKH (teamim-reference.ts). */
  book: string;
  num: number;
  aliyot: Aliyah[];
  haftarah?: string;
}

